import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { 
  Database, 
  CheckCircle, 
  RefreshCw, 
  AlertCircle, 
  Clock, 
  Trash2,
  UploadCloud
} from 'lucide-react';

const ProductUpload = () => {
  const [syncStatus, setSyncStatus] = useState(null);
  const [syncing, setSyncing] = useState(false);
  const [syncMessage, setSyncMessage] = useState({ text: '', type: '' });

  // Manual File Upload fallback state
  const [showManualUpload, setShowManualUpload] = useState(false);
  const [file, setFile] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [fileSuccessMsg, setFileSuccessMsg] = useState('');

  // Fetch Sync Status on mount
  const fetchSyncStatus = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/products/sync-status');
      setSyncStatus(response.data);
    } catch (error) {
      console.error('Error fetching sync status:', error);
    }
  };

  useEffect(() => {
    fetchSyncStatus();
  }, []);

  // Immediate Sync from Google Sheets (uses URL configured in backend .env)
  const handleSyncNow = async () => {
    setSyncing(true);
    setSyncMessage({ text: '', type: '' });
    try {
      const response = await axios.post('http://localhost:5000/api/products/sync-sheet', {});
      setSyncMessage({ 
        text: `تمت المزامنة بنجاح! تم تحديث ${response.data.count || 0} منتج.`, 
        type: 'success' 
      });
      await fetchSyncStatus();
    } catch (error) {
      console.error('Error syncing products:', error);
      const errMsg = error.response?.data?.message || error.message || 'Er';
      setSyncMessage({ text: errMsg, type: 'error' });
      await fetchSyncStatus();
    } finally {
      setSyncing(false);
    }
  };

  // Handle Manual File Upload fallback
  const handleFileChange = (e) => {
    if (e.target.files && e.target.files.length > 0) {
      setFile(e.target.files[0]);
      setFileSuccessMsg('');
    }
  };

  const handleManualUpload = async () => {
    if (!file) return;

    const formData = new FormData();
    formData.append('file', file);

    setUploading(true);
    try {
      const response = await axios.post('http://localhost:5000/api/products/upload', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      setFileSuccessMsg(response.data.message);
      setFile(null);
      await fetchSyncStatus();
    } catch (error) {
      console.error('Error uploading product file:', error);
      alert('حدث خطأ أثناء رفع الملف');
    } finally {
      setUploading(false);
    }
  };

  // Handle Clear Master Data
  const handleDeleteMaster = async () => {
    if (window.confirm('هل أنت متأكد من مسح جميع بيانات المنتجات (Master Data)؟')) {
      try {
        await axios.delete('http://localhost:5000/api/products/all');
        setSyncMessage({ text: 'تم مسح بيانات المنتجات بنجاح.', type: 'info' });
        await fetchSyncStatus();
      } catch (error) {
        console.error('Error deleting master data:', error);
        alert('حدث خطأ أثناء مسح البيانات');
      }
    }
  };

  const formatDateTime = (dateString) => {
    if (!dateString) return 'لم تتم بعد';
    const d = new Date(dateString);
    return d.toLocaleString('ar-EG', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  return (
    <div className="bg-white rounded-2xl shadow-sm border border-slate-100 p-6 flex flex-col justify-center">
      {/* Header */}
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <Database className="w-5 h-5 text-emerald-600" />
          <h3 className="text-lg font-bold text-slate-800">تحديث المنتجات (Products Master)</h3>
        </div>
        <button
          onClick={handleDeleteMaster}
          className="text-xs px-2.5 py-1 rounded-lg text-red-600 bg-red-50 hover:bg-red-100 font-medium transition-all border border-red-200"
          title="مسح جميع بيانات المنتجات"
        >
          مسح الكل
        </button>
      </div>

      {/* Schedule Info Banner */}
      <div className="bg-emerald-50 border border-emerald-100 rounded-xl p-3 mb-4 text-xs text-emerald-800 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Clock className="w-4 h-4 text-emerald-600 flex-shrink-0" />
          <span>
            <strong>التحديث التلقائي:</strong> يعمل يومياً الساعة <strong>06:00 صباحاً</strong>
          </span>
        </div>
        <button
          onClick={() => setShowManualUpload(!showManualUpload)}
          className="text-emerald-700 hover:text-emerald-900 underline text-xs font-semibold"
        >
          {showManualUpload ? 'إخفاء الرفع اليدوي' : 'رفع ملف يدوي'}
        </button>
      </div>

      {/* Primary Action: Sync Now Button */}
      <button
        onClick={handleSyncNow}
        disabled={syncing}
        className={`w-full py-3 px-4 rounded-xl text-white font-bold text-sm flex items-center justify-center gap-2.5 shadow-md transition-all ${
          syncing
            ? 'bg-emerald-400 cursor-not-allowed'
            : 'bg-emerald-600 hover:bg-emerald-700 hover:shadow-emerald-200 active:scale-[0.99]'
        }`}
      >
        <RefreshCw className={`w-4 h-4 ${syncing ? 'animate-spin' : ''}`} />
        <span>{syncing ? 'جاري مزامنة المنتجات من Google Sheets...' : 'مزامنة الآن (Sync Now)'}</span>
      </button>

      {/* Sync Message Alert */}
      {syncMessage.text && (
        <div
          className={`mt-3 p-3 rounded-xl text-xs flex items-start gap-2 ${
            syncMessage.type === 'success'
              ? 'bg-emerald-50 text-emerald-800 border border-emerald-200'
              : syncMessage.type === 'error'
              ? 'bg-red-50 text-red-800 border border-red-200'
              : 'bg-blue-50 text-blue-800 border border-blue-200'
          }`}
        >
          {syncMessage.type === 'success' ? (
            <CheckCircle className="w-4 h-4 flex-shrink-0 text-emerald-600 mt-0.5" />
          ) : (
            <AlertCircle className="w-4 h-4 flex-shrink-0 text-red-600 mt-0.5" />
          )}
          <span className="leading-snug">{syncMessage.text}</span>
        </div>
      )}

      {/* Status Info Footer */}
      {syncStatus && (
        <div className="mt-3 bg-slate-50 border border-slate-100 rounded-xl p-3 flex items-center justify-between text-xs text-slate-500">
          <div className="flex items-center gap-2">
            <span
              className={`w-2.5 h-2.5 rounded-full ${
                syncStatus.lastSyncStatus === 'success'
                  ? 'bg-emerald-500'
                  : syncStatus.lastSyncStatus === 'error'
                  ? 'bg-red-500'
                  : syncStatus.lastSyncStatus === 'running'
                  ? 'bg-amber-500 animate-ping'
                  : 'bg-slate-400'
              }`}
            />
            <span>آخر مزامنة: <strong>{formatDateTime(syncStatus.lastSyncAt)}</strong></span>
          </div>
          <div>
            إجمالي المنتجات: <strong className="text-slate-700">{syncStatus.totalProductsInDb || 0}</strong>
          </div>
        </div>
      )}

      {/* Collapsible Manual File Upload Fallback */}
      {showManualUpload && (
        <div className="mt-4 pt-4 border-t border-slate-200 flex flex-col gap-2.5">
          <div className="text-xs font-semibold text-slate-700 flex items-center gap-1.5">
            <UploadCloud className="w-4 h-4 text-slate-500" />
            <span>رفع ملف Excel / CSV محلي كبديل:</span>
          </div>
          <div>
            <label className="block w-full text-xs text-slate-500 file:mr-3 file:py-1.5 file:px-3 file:rounded-lg file:border-0 file:text-xs file:font-semibold file:bg-emerald-50 file:text-emerald-700 hover:file:bg-emerald-100 cursor-pointer border border-slate-200 rounded-xl p-1 bg-slate-50">
              <input 
                type="file" 
                accept=".csv, application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel" 
                onChange={handleFileChange}
                disabled={uploading}
                className="w-full"
              />
            </label>
          </div>
          <button
            onClick={handleManualUpload}
            disabled={!file || uploading}
            className={`py-2 px-3 rounded-xl text-white font-semibold text-xs transition-all ${
              !file || uploading 
                ? 'bg-slate-300 cursor-not-allowed' 
                : 'bg-slate-700 hover:bg-slate-800'
            }`}
          >
            {uploading ? 'جاري الرفع...' : 'رفع الملف المحدد'}
          </button>
          {fileSuccessMsg && (
            <div className="flex items-center gap-1.5 text-emerald-600 text-xs font-medium">
              <CheckCircle className="w-3.5 h-3.5" />
              {fileSuccessMsg}
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default ProductUpload;
